from pathlib import Path
import json
B=Path(__file__).parent;S=[];C={}
def add(k,title,text,form,notes):S.append(dict(id=k,title=title,text=text));C[k]=dict(form=form,notes=notes)
add('hello','路口突然封了，还要从头算吗？','大家好，我是硅宝。老板刚夸我把路线算明白，转身就在路口放了三箱货。我说，刚才的计算白做了？老板说，地图只改了这么一点，你怎么把整张草稿纸都扔了？今天研究一件省事的事：环境变了，能不能保留算过的部分，只修需要修的地方。',[r'\text{reuse}+\text{repair}'],['第23集 · 环境变化与搜索复用','LPA*：Lifelong Planning A*','原人物、三维教学与实际搜索日志'])
add('bridge','从静态找路，进入图变化与复用','前面几集，我们比较了静态地图上的搜索、采样和优化。现在开启环境变化与搜索复用专题，先讲 L P A 星，终身规划 A 星。这个名字里的终身，不是给机器人办终身会员，而是反复解决相似问题时，把以前的搜索信息留下来。它是经典增量搜索，不是刚出现的新算法。',[r'\text{A*}\to\text{LPA*}'],['经典增量启发式搜索','本集固定起点与终点','改变图代价，再求当前图最短路'])
add('setup','先限定：地图更新时，机器人没有移动','实验是一张二十三乘十五的四邻接栅格，有两排货架。起点和终点固定；通常相邻两格的边代价是一，封住格子就把相关边设为不可通行。地图在两次查询之间更新。这里没有模拟行人未来的位置，也没有让小车边走边感知。动画光点只展示路径，不代表已经解决动态避碰。',[r'c(u,v)\geq1',r'h(v)=|x_v-x_T|+|y_v-y_T|'],['固定起终点，地图快照逐次更新','四邻接，不走对角线','曼哈顿启发在所有代价版本中保持一致'])
add('baseline','第一次搜索，先交同一份作业','先在原图上找路。初始路线代价二十，L P A 星和从头运行的 A 星，都扩展了二十一个节点。这里把从有效队列取出并处理一次节点，记作一次扩展，包含终点。两者使用同一张图、同一启发和偏向较小起点代价的平局规则。第一次没有旧结果可用，不能凭空省掉这份工作。',[r'C_{initial}=20',r'N_{LPA*}=N_{A*}=21'],['实际初始搜索：21次对21次','扩展事件不是唯一格子数','不是论文或工程库性能复现'])
add('gvalue','第一本账：保存下来的起点代价估计','想复用，就得先保存状态。第一本账叫起点代价估计，记作小写的 g。它表示程序当前保存的，从起点到某个节点的代价估计。地图变化以后，这笔旧账可能偏大，也可能已经过时地偏小。它不是机器人已经行驶的里程，更不能看到一个旧数值，就认定新地图仍然能走。',[r'g(v):\ \text{stored estimate}'],['g是算法保存的估计','地图变化后可能失效','不是机器人累计行驶距离'])
add('rhs','第二本账：按前驱重新报一次价','第二本账叫一步前瞻值，写作 r h s。对起点，它固定为零；对其他节点，把每个前驱的旧账，加上连接过来的当前边代价，再取最小值。可以把它理解成：根据邻居目前的报价，我这里应该报多少？这仍依赖邻居的状态，不是一次局部计算就自动得到全部正确答案。',[r'rhs(S)=0',r'rhs(v)=\min_{u\in Pred(v)}[g(u)+c(u,v)]'],['前驱到当前节点，方向不能写反','rhs根据当前边代价重算','本实验是无向栅格，前驱与邻居相同'])
add('consistent','两本账对不上，就是待处理节点','两本账相等，叫局部一致；不相等，就需要进入待处理队列。注意局部两个字：一个节点账目对上，不等于全图已经正确，也不等于机器人一定能安全执行。算法沿着受影响的后继传播更新，再由终点状态和队列条件一起决定能不能停止。',[r'g(v)=rhs(v)',r'g(v)\neq rhs(v)\Rightarrow v\in U'],['局部一致，不是全局验收结论','队列维护所有当前不一致节点','只按优先级处理与当前查询相关的部分'])
add('hand','独立手算：一条边涨价，旧账变便宜了','做个独立小例子。甲的旧账是二，乙是三；它们到节点 V 的边代价分别是一和二，所以 V 的一步报价是三，旧账也等于三。现在甲这条边从一涨到五，新报价变成二加五，与三加二之间的较小值，也就是五。旧账三还留着，就显得比真实情况过于乐观。',[r'rhs_{old}(V)=\min(2+1,3+2)=3',r'rhs_{new}(V)=\min(2+5,3+2)=5'],['独立手算，不是栅格地图的数据','边涨价：g=3，rhs=5','旧的低代价可能依赖已经失效的边'])
add('increase','旧账偏小：先撤销，再向后传播','当旧账小于新报价，不能只把当前节点改成五就收工。它的后继可能还在引用旧的三。基础版算法先把这个节点的旧账设为无穷大，再更新它自己和后继，让依赖旧账的地方一起重新报价。这里的撤销与重算，是处理封路和代价上涨的关键。',[r'g(v)<rhs(v)\Rightarrow g(v)\leftarrow\infty',r'\text{update }\{v\}\cup Succ(v)'],['先撤销过时的乐观估计','再更新自身与后继','保留基础LPA*两种处理分支'])
add('decrease','旧账偏大：接受更低报价，再通知后继','反过来，道路重新开放，或者某条边降价，可能出现旧账五、一步报价三。这时可以接受更低的报价，把旧账改成三，再通知后继继续更新。初始化时，起点旧账无穷大、一步报价零，也通过这条分支开始传播。两种方向都要处理，不能只会修封路，不会发现重新开放的捷径。',[r'g(v)>rhs(v)\Rightarrow g(v)\leftarrow rhs(v)',r'g(S)=\infty,\quad rhs(S)=0'],['降价与重新开放也能触发修复','接受报价后更新后继','g、rhs、队列跨查询保留'])
add('key','谁先处理：两个数按顺序比较','待处理节点也要排队。先取旧账和新报价里较小的数，加上到终点的启发值，作为第一关键字；较小的那个代价值本身，作为第二关键字。先比第一个，相等再比第二个。本集用曼哈顿距离，所有可走边代价至少为一，因此地图改前改后都保持启发一致。',[r'm(v)=\min(g(v),rhs(v))',r'K(v)=[m(v)+h(v),\ m(v)]'],['字典序：先第一项，再第二项','不是把两个关键字再加成一个数','启发一致性依赖当前图代价条件'])
add('stop','停止时，终点和队首都要检查','什么时候可以交作业？终点两本账要相等，而且队列里不能还有关键字更小、需要优先处理的节点。两个条件缺一个都不行。算法不要求把所有格子都重新整理完。初次搜索结束时，实验里仍有四十四个不一致节点留在队列，当前终点路线却已经满足停止条件。',[r'g(T)=rhs(T)',r'TopKey(U)\geq K(T)'],['两个停止条件同时满足','队列非空不等于尚未找到最短路','所有数值在本有限正权图内解释'])
add('closure','真实封路：旧路线失效，重新修复','现在把靠近终点的三个格子封住，原来的直线路径会穿过货箱，必须作废。程序先更新受影响的边，再更新这些有向边的终点报价，最后运行修复。新路线代价二十四；L P A 星扩展九十二次，重新运行 A 星扩展一百零五次。两条结果都和独立的最短路核验器一致。',[r'C_{closed}=24',r'N_{repair}=92,\quad N_{restart}=105'],['真实日志：封格后相关边设为无穷大','地图先完整更新，再修复rhs','旧路线不得继续当成可执行路线'])
add('reopen','道路恢复：这一次，只扩展了四次','接着搬走那三箱货。旧搜索状态继续保留，恢复的边代价变回一。路线重新缩短到二十，L P A 星这次只扩展四次，从头运行 A 星还是二十一次。再把一小段通道代价提高到四，路线选择绕行；把代价降回来，算法也能重新发现原来的便宜通道。',[r'C_{reopen}=20',r'N_{repair}=4,\quad N_{restart}=21'],['复用来自之前查询留下的搜索信息','代价升高与降低都实际运行','同一更新序列，不能只截取最省事的一次'])
add('cost','少扩展，不自动等于运行更快','但别急着把二十一次除以四，就宣布速度快了五倍。增量搜索还要重算前驱报价、维护队列、丢弃过期队列项。刚才恢复道路虽然只扩展四次，仍扫描了一百零七条前驱邻接关系；从头 A 星扫描八十次后继邻接。两项来自不同操作，不能当成同一份耗时，也不能把额外维护藏起来。',[r'N_{pop}\neq T_{wall}',r'T=T_{diff}+T_{rhs}+T_{queue}+T_{search}'],['扩展、邻接扫描、队列操作分别记账','地图变化检测成本不在搜索计数内','没有跨实现、跨硬件速度排名'])
add('counter','反例：变化靠近起点，复用也可能更费事','再看同一更新序列的最后一步：把起点附近的三个格子封住。这次 L P A 星扩展七十七次，重新运行 A 星只扩展六十五次。早期路径信息失效，可能影响很大一片后继。增量不代表修改了三个格子，就永远只处理三个格子。改动的位置、旧状态和图结构，都会影响修复成本。',[r'N_{repair}=77>65=N_{restart}'],['实际反例，保留此前更新历史','少量改动也可能引发广泛传播','不保证每次都比重新搜索省工作'])
add('failure','故意把通道彻底切断：这次真的无路','现在把一整列格子封住，地图被切成两半。修复结束后，终点旧账和一步报价都为无穷大，程序明确返回没有路径，而不是拿旧路线凑数。接着只打开墙上的一个门，再次修复，代价二十的路线恢复。这两次变化，都重新核对了每一步的邻接、通行状态和总代价。',[r'g(T)=rhs(T)=\infty\Rightarrow\text{no path}'],['在当前有限栅格图上无路','不是未知现实世界无路的证明','开门后重新计算，不复用失效路径'])
add('verify','验收：每张新图，都找独立答案核对','除了这条主演示序列，我们还用三个随机种子，各生成三十次地图格子开关，共九十次更新。每次都与从头 A 星、另一个反向迪杰斯特拉核验器对照最短代价，并检查返回路线。实验通过，说明这份教学实现覆盖了这些测试，不能把九十次测试说成对所有机器人场景的工程保证。',[r'C_{LPA*}=C_{A*}=C_{oracle}'],['三个种子是三条独立随机更新序列','90次随机更新 + 主演示8阶段','栅格图正确性不代替车身、控制与真机验收'])
add('boundary','会修图，还不等于会躲开走动的人','最后分清三个问题：地图的边代价变了，机器人起点移动了，障碍物在未来什么时候出现。本集解决第一个，起终点一直固定。移动起点可以继续研究 D 星 Lite；行人预测、时间维度和紧急制动，还要另加模型与安全机制。我能修草稿纸，不代表已经可以闭眼穿过仓库。',[r'\text{graph updates}\neq\text{timed avoidance}'],['本集不做移动起点D* Lite','没有未来障碍占用、时间窗口或实时预算保证','几何回放不代表机器人执行'])
add('close','带走三句话：旧账、报价、按需修复','今天带走三句话：保存旧的代价估计，用一步报价找出不一致，再按优先级修到当前终点满足条件。旧结果能省下多少工作，要让实验说话。我是硅宝。老板问路修好了吗？我说好了。老板又问，刚才挡路的三箱货，谁搬走？看来有些增量更新，最后还得靠体力。',[r'\text{store}\to\text{compare}\to\text{repair}'],['LPA* / 终身规划A* · 第23集','实际搜索日志、讲义与代码保留','画面与配音含AI辅助制作'])
(B/'lesson.json').write_text(json.dumps(S,ensure_ascii=False,indent=2));(B/'cards.json').write_text(json.dumps(C,ensure_ascii=False,indent=2));print('chapters',len(S),'chars',sum(len(c['text'])for c in S))
